  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law prohibits a physician from performing an abortion after 15 weeks of gestation, except when necessary to prevent the death of the pregnant woman or a serious risk of substantial and irreversible physical impairment. The measure repeals this limit and makes abortion lawful at any point before fetal viability.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Physicians will be able to provide, and patients will be able to seek, abortion services between 15 weeks and fetal viability without legal penalty, which may reduce the number of patients traveling out of state for such care.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the restriction on accessing abortion care between 15 weeks and viability, removing the state's barrier to patients receiving care and physicians providing it during this stage of pregnancy.",
      "disputed": false
    }
  ],
